import { NextRequest } from "next/server";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { GET } from "../../../app/api/handle-availability/route";
import { CREATOR_HANDLE_MAX, CREATOR_HANDLE_MIN } from "../creator-handle";
import { validateHandle } from "../handle_rule";

// All-pairs matrix generated by Microsoft PICT from web/src/lib/__tests__/handle_pairwise.model.txt.
// Column order: HandleLength, Charset, PublishableKey, Limiter, RpcResult. 43 rows; every value pair is covered.
// Inlined, not generated at runtime, so the matrix is reviewable and the test has no tool dependency.
type Row = [length: string, charset: string, key: string, limiter: string, rpc: string];

const PAIRWISE_ROWS: Row[] = [
  ["2", "lowercase", "absent", "allowed", "null"],
  ["1", "uppercase", "present", "unavailable", "true"],
  ["64", "lowercase", "present", "limited", "truthy_string"],
  ["63", "unicode", "absent", "limited", "error"],
  ["2", "unicode", "present", "unavailable", "false"],
  ["65", "digit", "present", "allowed", "true"],
  ["64", "hyphen", "absent", "allowed", "false"],
  ["63", "digit", "absent", "unavailable", "truthy_string"],
  ["1", "lowercase", "present", "allowed", "error"],
  ["1", "underscore", "absent", "limited", "null"],
  ["1", "digit", "present", "limited", "false"],
  ["3", "unicode", "absent", "limited", "true"],
  ["3", "underscore", "present", "allowed", "truthy_string"],
  ["1", "period", "absent", "limited", "truthy_string"],
  ["63", "underscore", "present", "unavailable", "false"],
  ["3", "lowercase", "present", "unavailable", "false"],
  ["1", "unicode", "present", "allowed", "null"],
  ["63", "hyphen", "present", "unavailable", "null"],
  ["64", "unicode", "present", "unavailable", "error"],
  ["65", "unicode", "absent", "unavailable", "truthy_string"],
  ["64", "period", "present", "unavailable", "true"],
  ["2", "uppercase", "absent", "limited", "truthy_string"],
  ["65", "hyphen", "absent", "limited", "error"],
  ["3", "hyphen", "absent", "limited", "true"],
  ["2", "digit", "present", "allowed", "error"],
  ["63", "uppercase", "absent", "allowed", "false"],
  ["65", "lowercase", "present", "allowed", "true"],
  ["2", "hyphen", "present", "allowed", "true"],
  ["3", "period", "absent", "allowed", "null"],
  ["65", "period", "present", "allowed", "false"],
  ["64", "uppercase", "present", "unavailable", "null"],
  ["64", "digit", "present", "limited", "null"],
  ["3", "digit", "present", "limited", "error"],
  ["1", "hyphen", "present", "unavailable", "truthy_string"],
  ["65", "uppercase", "present", "allowed", "error"],
  ["2", "period", "absent", "unavailable", "error"],
  ["65", "underscore", "present", "limited", "error"],
  ["3", "uppercase", "present", "unavailable", "error"],
  ["63", "lowercase", "absent", "unavailable", "true"],
  ["64", "underscore", "present", "unavailable", "true"],
  ["2", "underscore", "absent", "unavailable", "true"],
  ["65", "uppercase", "absent", "unavailable", "null"],
  ["63", "period", "absent", "limited", "error"],
];

// One representative character per charset class. "unicode" is a BMP character, so string length equals the
// character count the route's regex sees.
const CHARS: Record<string, string> = {
  lowercase: "a",
  digit: "7",
  underscore: "_",
  hyphen: "-",
  uppercase: "A",
  period: ".",
  unicode: "é",
};
const CHARSET_IS_VALID: Record<string, boolean> = {
  lowercase: true,
  digit: true,
  underscore: true,
  hyphen: true,
  uppercase: false,
  period: false,
  unicode: false,
};

const clientState = vi.hoisted(() => ({
  rpcResult: { data: null as unknown, error: null as unknown },
  calls: [] as { url: string; key: string }[],
  rpcArgs: [] as { name: string; args: unknown }[],
}));

vi.mock("@supabase/supabase-js", () => ({
  createClient: (url: string, key: string) => {
    clientState.calls.push({ url, key });
    return {
      rpc: async (name: string, args: unknown) => {
        clientState.rpcArgs.push({ name, args });
        return clientState.rpcResult;
      },
    };
  },
}));

const limiter = vi.hoisted(() => ({
  decide: async (_ip: string): Promise<unknown> => ({ kind: "allowed" }),
}));
vi.mock("../handle_ratelimit", () => ({
  checkHandleRateLimit: (ip: string) => limiter.decide(ip),
}));

const sentry = vi.hoisted(() => ({ calls: [] as unknown[][] }));
vi.mock("@sentry/nextjs", () => ({
  captureException: (...args: unknown[]) => {
    sentry.calls.push(args);
  },
}));

const PUBLISHABLE_KEY = "pub-key-for-tests";
const SECRET_KEY = "secret-key-must-not-be-used";
const RPC_ERROR_MESSAGE = "relation handle_probe_internal does not exist";

function handleFor(length: number, charset: string): string {
  const ch = CHARS[charset];
  if (ch === undefined) throw new Error(`unmapped charset: ${charset}`);
  return ch.repeat(length);
}

function limiterDecision(value: string): unknown {
  switch (value) {
    case "allowed":
      return { kind: "allowed" };
    case "limited":
      return { kind: "limited", retryAfterSeconds: 7 };
    case "unavailable":
      return { kind: "unavailable" };
    default:
      throw new Error(`unmapped limiter value: ${value}`);
  }
}

function rpcResultFor(value: string): { data: unknown; error: unknown } {
  switch (value) {
    case "true":
      return { data: true, error: null };
    case "false":
      return { data: false, error: null };
    case "null":
      return { data: null, error: null };
    case "error":
      return { data: null, error: { code: "42883", message: RPC_ERROR_MESSAGE } };
    case "truthy_string":
      return { data: "true", error: null };
    default:
      throw new Error(`unmapped rpc value: ${value}`);
  }
}

function setRow(row: Row): void {
  const [, , key, limiterValue, rpc] = row;
  vi.stubEnv("SUPABASE_URL", "https://project.example.test");
  vi.stubEnv("SUPABASE_PUBLISHABLE_KEY", key === "present" ? PUBLISHABLE_KEY : "");
  vi.stubEnv("SUPABASE_SECRET_KEY", SECRET_KEY);
  const decision = limiterDecision(limiterValue);
  limiter.decide = async () => decision;
  clientState.rpcResult = rpcResultFor(rpc);
}

// Expected outcome, following the branch order of web/app/api/handle-availability/route.ts GET:
//   1. rate limit first (lines 37-44): limited -> 429, unavailable -> 503, before any handle or key check
//   2. handle validation (lines 46-49), using the route's own validator: invalid -> 400
//   3. configuration (lines 51-58): publishable key absent -> 503, Sentry stage "config", no client built
//   4. RPC (lines 60-74): boolean true/false -> 200 with available; anything else -> 503, Sentry stage "query"
type Expected = {
  status: 200 | 400 | 429 | 503;
  available?: boolean;
  rpcCalled: boolean;
  sentryStage: "config" | "query" | null;
};

function expectedFor(handle: string, row: Row): Expected {
  const [, , key, limiterValue, rpc] = row;
  if (limiterValue === "limited") return { status: 429, rpcCalled: false, sentryStage: null };
  if (limiterValue === "unavailable") return { status: 503, rpcCalled: false, sentryStage: null };
  if (!validateHandle(handle).ok) return { status: 400, rpcCalled: false, sentryStage: null };
  if (key === "absent") return { status: 503, rpcCalled: false, sentryStage: "config" };
  if (rpc === "true") return { status: 200, available: true, rpcCalled: true, sentryStage: null };
  if (rpc === "false") return { status: 200, available: false, rpcCalled: true, sentryStage: null };
  return { status: 503, rpcCalled: true, sentryStage: "query" };
}

// Independent statement of the handle rule from the constants (creator-handle.ts), compared with the route's validator.
function modelSaysValid(length: number, charset: string): boolean {
  return length >= CREATOR_HANDLE_MIN && length <= CREATOR_HANDLE_MAX && CHARSET_IS_VALID[charset] === true;
}

let consoleErrorSpy: ReturnType<typeof vi.spyOn> | undefined;

beforeEach(() => {
  clientState.rpcResult = { data: null, error: null };
  clientState.calls = [];
  clientState.rpcArgs = [];
  sentry.calls = [];
  limiter.decide = async () => ({ kind: "allowed" });
  // The route logs each failure with console.error; silence it so the matrix output stays readable.
  consoleErrorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
});

afterEach(() => {
  consoleErrorSpy?.mockRestore();
  vi.unstubAllEnvs();
});

describe("GET /api/handle-availability: pairwise matrix (PICT all-pairs)", () => {
  it("the inlined matrix covers every value pair of every two columns", () => {
    const columns = 5;
    const values: string[][] = Array.from({ length: columns }, (_, c) => [...new Set(PAIRWISE_ROWS.map((r) => r[c]))]);
    for (let a = 0; a < columns; a++) {
      for (let b = a + 1; b < columns; b++) {
        for (const va of values[a]) {
          for (const vb of values[b]) {
            expect(PAIRWISE_ROWS.some((r) => r[a] === va && r[b] === vb)).toBe(true);
          }
        }
      }
    }
  });

  it.each(PAIRWISE_ROWS)(
    "length=%s charset=%s key=%s limiter=%s rpc=%s",
    async (length, charset, key, limiterValue, rpc) => {
      const row: Row = [length, charset, key, limiterValue, rpc];
      setRow(row);
      const handle = handleFor(Number(length), charset);
      const url = new URL("http://localhost/api/handle-availability");
      url.searchParams.set("handle", handle);

      const res = await GET(new NextRequest(url.toString()));
      const want = expectedFor(handle, row);

      expect(res.status).toBe(want.status);
      expect(res.headers.get("Cache-Control")).toBe("no-store");
      const text = await res.text();
      const body = JSON.parse(text) as Record<string, unknown>;
      if (want.status === 200) {
        expect(body).toEqual({ available: want.available, handle });
      } else {
        expect(typeof body.error).toBe("string");
        expect(body).not.toHaveProperty("available");
      }
      if (want.status === 429) expect(res.headers.get("Retry-After")).toBe("7");

      // No lookup on 400, 429, 503-unavailable, or a missing publishable key.
      expect(clientState.rpcArgs.length).toBe(want.rpcCalled ? 1 : 0);
      if (want.rpcCalled) {
        expect(clientState.rpcArgs).toEqual([{ name: "handle_available", args: { p_handle: handle } }]);
      }
      // The publishable key only, never the secret key.
      for (const call of clientState.calls) {
        expect(call.key).toBe(PUBLISHABLE_KEY);
        expect(call.key).not.toBe(SECRET_KEY);
      }
      // Sentry gets one event, tagged with the stage, when the route reports a failure.
      expect(sentry.calls.length).toBe(want.sentryStage ? 1 : 0);
      if (want.sentryStage) {
        expect((sentry.calls[0][1] as { tags: { stage: string } }).tags.stage).toBe(want.sentryStage);
      }
      // The RPC error message never reaches the response body.
      expect(text).not.toContain(RPC_ERROR_MESSAGE);

      // Route validator and the constant-based rule must agree for this handle.
      expect(validateHandle(handle).ok).toBe(modelSaysValid(Number(length), charset));
    },
  );
});
